-- Independent bounded snapshot; no changes to S13 economic_indicators or COFOG.
CREATE TABLE public.fiscal_sector_accounts (
  geo text NOT NULL CHECK (geo='ES'),
  sector text NOT NULL CHECK (sector IN ('S13','S1311','S1312','S1313','S1314')),
  year integer NOT NULL CHECK (year BETWEEN 2016 AND 2100),
  item text NOT NULL CHECK (item IN ('TR','TE','B9')),
  value numeric(18,3) NOT NULL CHECK (value <> 'NaN'::numeric AND (item='B9' OR value>=0)),
  unit text NOT NULL CHECK (unit='MIO_EUR'),
  raw_data jsonb NOT NULL,
  PRIMARY KEY (geo,sector,year,item)
);
ALTER TABLE public.fiscal_sector_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY fiscal_sector_accounts_read ON public.fiscal_sector_accounts FOR SELECT TO anon, authenticated USING(true);
GRANT SELECT ON public.fiscal_sector_accounts TO anon, authenticated;
GRANT ALL ON public.fiscal_sector_accounts TO service_role;

